mapper.select:
SELECT c.id_cita as idCita, DATE_FORMAT(c.fecha_cita, '%Y-%m-%d') as fechaCita, c.hora_cita as horaCita, c.id_paciente as idPaciente, c.id_medico as idMedico, c.observaciones as observaciones, c.estatus as estatus, c.motivo_cancelacion as motivoCancelacion, DATE_FORMAT(c.fecha_creacion, '%Y-%m-%d %H:%i:%s') as fechaCreacion, p.nombre as pacienteNombre, p.primer_apellido as pacientePrimerApellido, p.segundo_apellido as pacienteSegundoApellido, p.email as pacienteEmail, m.nombre as medicoNombre, m.primer_apellido as medicoPrimerApellido, m.segundo_apellido as medicoSegundoApellido FROM cita c INNER JOIN paciente p ON c.id_paciente = p.id_paciente INNER JOIN medico m ON c.id_medico = m.id_medico
AND c.id_medico = #{idMedico}
AND c.estatus = #{estatus}
AND ( p.nombre LIKE CONCAT('%', #{criterio}, '%') OR p.primer_apellido LIKE CONCAT('%', #{criterio}, '%') OR p.segundo_apellido LIKE CONCAT('%', #{criterio}, '%') OR p.email LIKE CONCAT('%', #{criterio}, '%') )

mapper.update:
UPDATE cita 
SET estatus = 'Cancelada', 
motivo_cancelacion = #{motivoCancelacion} 
WHERE id_cita = #{idCita}
